                // Otherwise, if next arg doesn't start with "-", we could treat it as topic, but only if we already have abi_path and event_name? No, topics can be before abi.
                // For simplicity, we will consume only one topic per -l, so break here to avoid greedily consuming positional.
                break;
            }
        } else if a.starts_with("-") {
            eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context", a);
            eprintln!();
            eprintln!("USAGE:");
