        std::process::exit(1);
    }
    match crate::ethabi::decode_log(&abi_path.unwrap(), &event_name.unwrap(), &data.unwrap(), &topics) {
        Ok(lines) => { for l in lines { println!("{}", l); } },
        Err(e) => { eprintln!("Error: {}", e); std::process::exit(1); }
    }
}

