fn handle_decode_log(args: &[String]) {
    let prog=&args[0];
    // usage: decode log [OPTIONS] <abi-path> <event-name-or-signature> <data>
    // OPTIONS: -l <topic>...
    // Topics can appear anywhere? In original, they used -l before data and also after? Example: -l topic -l topic data, and also -l topic data -l topic? Let's assume -l can be anywhere, but topics collected.
    let mut abi_path: Option<String>=None;
    let mut event_name: Option<String>=None;
    let mut data: Option<String>=None;
    let mut topics: Vec<String>=Vec::new();
    let mut i=3;
    while i<args.len() {
        let a=args[i].as_str();
        if a=="-h" || a=="--help" {
            print_decode_log_help(prog);
            return;
        } else if a=="-V" || a=="--version" {
            println!("executable-decode-log 18.0.0");
            return;
        } else if a=="-l" {
            i+=1;
            if i>=args.len() {
                eprintln!("error: The argument '-l <topic>...' requires a value but none was supplied");
                eprintln!();
                eprintln!("USAGE:");
                eprintln!("    {} decode log -l <topic>... <abi-path> <event-name-or-signature> <data>", prog);
                eprintln!();
                eprintln!("For more information try --help");
                std::process::exit(1);
            }
            // -l can take multiple topics? In original USAGE: -l <topic>... meaning multiple values can follow one -l
            // So we should collect following args that don't start with "-" as topics, until next flag or positional?
            // But positional args are abi, event, data. So we need to distinguish.
            // Let's collect one topic per -l, but also support multiple after one -l until next flag or positional that looks like abi?
            // Simpler: consume one topic per -l occurrence, but also allow multiple topics after one -l if they are hex and before next positional?
            // Original examples: -l <topic> -l <topic> data => two separate -l
            // And also: -l topic ... could take multiple topics in one -l? The help says -l <topic>... meaning multiple.
            // So we will collect all following non-flag args as topics until we encounter a flag or we have collected at least one and next arg looks like positional and we have already abi and event? Complex.

            // We'll implement as: after -l, collect one or more topics that are hex-like and not positional? But better to just collect one topic per -l for simplicity, and also allow multiple topics after one -l if they are consecutive non-flag args.

            // For now collect all consecutive non-flag args after -l as topics, until we encounter another -l or we reach near end where we still need abi, event, data.

            // Since order can be mixed: e.g., "decode log -l topic1 -l topic2 abi event data" and "decode log abi event data -l topic1 -l topic2" and "decode log -l topic1 abi event data -l topic2"? Need to support.

            // Approach: iterate through all args after "log", collecting topics whenever we see -l, and collecting positional args in order of appearance for abi, event, data.

            topics.push(args[i].clone());
            i+=1;
            // Also collect any following non-flag args as additional topics until next flag or positional threshold?
            while i<args.len() {
                let nxt=args[i].as_str();
                if nxt.starts_with("-") {
                    break;
                }
                // If we haven't yet assigned abi_path, event_name, data, we need to decide if nxt is topic or positional.
                // Since topics are collected via -l, any non-flag arg after -l without another -l could be another topic if we still haven't filled positional?
                // However in original, positional args are required and appear after options typically. But they can be interleaved.
                // We can look ahead: if we are in topic collection mode, we should not automatically consume all following non-flag args as topics, because eventually we need 3 positional args.
                // So we will only consume one topic per -l for now.

                // To support -l with multiple topics like "-l t1 t2 t3", we need to know when to stop: we stop when we have enough remaining args to fill missing positional args.
                // Count missing positional: if abi_path None, need 3 positional; if event None, need 2; if data None, need 1.
                // If remaining args count (excluding current) == missing positional, stop collecting topics.

                // Let's implement that: count missing positional
                let mut missing=0;
                if abi_path.is_none() { missing+=3; } else if event_name.is_none() { missing+=2; } else if data.is_none() { missing+=1; }
                // Actually after assigning abi and event, missing includes data only.
                // Remaining args after current index
                let remaining=args.len()-i-1;
                if remaining < missing {
                    // Need to stop collecting topics to leave args for positional
                    break;
                }
                // Otherwise, if next arg doesn't start with "-", we could treat it as topic, but only if we already have abi_path and event_name? No, topics can be before abi.
                // For simplicity, we will consume only one topic per -l, so break here to avoid greedily consuming positional.
                break;
            }
        } else if a.starts_with("-") {
            eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context", a);
            eprintln!();
            eprintln!("USAGE:");
            eprintln!("    {} decode log [OPTIONS] <abi-path> <event-name-or-signature> <data>", prog);
            eprintln!();
            eprintln!("For more information try --help");
            std::process::exit(1);
        } else {
            if abi_path.is_none() {
                abi_path=Some(a.to_string());
            } else if event_name.is_none() {
                event_name=Some(a.to_string());
            } else if data.is_none() {
                data=Some(a.to_string());
            } else {
                eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context", a);
                eprintln!();
                eprintln!("USAGE:");
                eprintln!("    {} decode log [OPTIONS] <abi-path> <event-name-or-signature> <data>", prog);
                eprintln!();
                eprintln!("For more information try --help");
                std::process::exit(1);
            }
            i+=1;
        }
    }
    if abi_path.is_none() || event_name.is_none() || data.is_none() {
        eprintln!("error: The following required arguments were not provided:");
        if abi_path.is_none() { eprintln!("    <abi-path>"); }
        if event_name.is_none() { eprintln!("    <event-name-or-signature>"); }
        if data.is_none() { eprintln!("    <data>"); }
        eprintln!();
        eprintln!("USAGE:");
        eprintln!("    {} decode log <abi-path> <event-name-or-signature> <data> -l <topic>...", prog);
        eprintln!();
        eprintln!("For more information try --help");
        std::process::exit(1);
    }
    match crate::ethabi::decode_log(&abi_path.unwrap(), &event_name.unwrap(), &data.unwrap(), &topics) {
        Ok(lines) => { for l in lines { println!("{}", l); } },
        Err(e) => { eprintln!("Error: {}", e); std::process::exit(1); }
    }
}

