pub fn parse_abi_file(path: &str) -> Result<Vec<AbiEntry>, String> {
    let content = std::fs::read_to_string(path).map_err(|e| format!("Failed to read ABI: {}", e))?;
    let json: serde_json::Value = serde_json::from_str(&content).map_err(|e| format!("Invalid ABI JSON: {}", e))?;
    let arr = json.as_array().ok_or("ABI is not array")?;
    let mut entries = Vec::new();
    for item in arr {
        let typ = item.get("type").and_then(|v| v.as_str()).unwrap_or("");
        match typ {
            "function" => {
                let name = item.get("name").and_then(|v| v.as_str()).unwrap_or("").to_string();
                let inputs = parse_params(item.get("inputs").and_then(|v| v.as_array()));
                let outputs = parse_params(item.get("outputs").and_then(|v| v.as_array()));
                entries.push(AbiEntry::Function(AbiFunction { name, inputs, outputs }));
            },
            "event" => {
                let name = item.get("name").and_then(|v| v.as_str()).unwrap_or("").to_string();
                let anonymous = item.get("anonymous").and_then(|v| v.as_bool()).unwrap_or(false);
                let inputs = parse_params(item.get("inputs").and_then(|v| v.as_array()));
                entries.push(AbiEntry::Event(AbiEvent { name, inputs, anonymous }));
            },
            "constructor" => {
                let inputs = parse_params(item.get("inputs").and_then(|v| v.as_array()));
                entries.push(AbiEntry::Constructor { inputs });
            },
            "fallback" => entries.push(AbiEntry::Fallback),
            "receive" => entries.push(AbiEntry::Receive),
            _ => {}
        }
    }
    Ok(entries)
}

fn parse_params(arr_opt: Option<&Vec<serde_json::Value>>) -> Vec<AbiParam> {
    let mut res = Vec::new();
    if let Some(arr) = arr_opt {
        for item in arr {
            let name = item.get("name").and_then(|v| v.as_str()).unwrap_or("").to_string();
            let type_str = item.get("type").and_then(|v| v.as_str()).unwrap_or("").to_string();
            let indexed = item.get("indexed").and_then(|v| v.as_bool()).unwrap_or(false);
            let param_type = match parse_param_type(&type_str) {
                Ok(t) => t,
                Err(_) => continue,
            };
            res.push(AbiParam { name, type_str, param_type, indexed });
        }
    }
    res
}

pub fn parse_param_type(s: &str) -> Result<ParamType, String> {
    let s = s.trim();
    // Tuple detection: starts with '(' and ends with ')'
    if s.starts_with('(') && s.ends_with(')') {
        // Check if it's a tuple with components, need to parse inside, respecting nested parentheses and brackets
        // For tuple, inside may be like "bool,uint256" or "(bool,uint256),uint256" etc
        let inner = &s[1..s.len()-1];
        if inner.is_empty() {
            return Ok(ParamType::Tuple(vec![]));
        }
        let types = split_tuple(inner)?;
        let mut vec = Vec::new();
        for t in types {
            vec.push(parse_param_type(&t)?);
        }
        return Ok(ParamType::Tuple(vec));
    }
    // Array detection: ends with ] 
    if s.ends_with(']') {
        // Find last '['
        // Need to handle nested like uint256[][] etc - recursively
        if let Some(bracket_pos) = s.rfind('[') {
            let base = &s[..bracket_pos];
            let len_part = &s[bracket_pos+1..s.len()-1];
            let inner_type = parse_param_type(base)?;
            if len_part.is_empty() {
                return Ok(ParamType::Array(Box::new(inner_type)));
            } else {
                // fixed array length
                let len = len_part.parse::<usize>().map_err(|_| format!("Invalid array length {}", len_part))?;
                return Ok(ParamType::FixedArray(Box::new(inner_type), len));
            }
        }
    }
    // Elementary types
    if s == "bool" {
        return Ok(ParamType::Bool);
    }
    if s == "address" {
        return Ok(ParamType::Address);
    }
    if s == "string" {
        return Ok(ParamType::String);
    }
    if s == "bytes" {
        return Ok(ParamType::Bytes);
    }
    if s.starts_with("bytes") && s.len() > 5 {
        let num_str = &s[5..];
        if let Ok(n) = num_str.parse::<usize>() {
            if n >=1 && n <=32 {
                return Ok(ParamType::FixedBytes(n));
            }
        }
    }
    if s.starts_with("uint") {
        let num_str = &s[4..];
        if let Ok(n) = num_str.parse::<usize>() {
            if n >=8 && n <=256 && n % 8 ==0 {
                return Ok(ParamType::Uint(n));
            }
        }
        if s == "uint" {
            return Ok(ParamType::Uint(256));
        }
    }
    if s.starts_with("int") {
        let num_str = &s[3..];
        if let Ok(n) = num_str.parse::<usize>() {
            if n >=8 && n <=256 && n % 8 ==0 {
                return Ok(ParamType::Int(n));
            }
        }
        if s == "int" {
            return Ok(ParamType::Int(256));
        }
    }
    Err(format!("Unknown type {}", s))
}

fn split_tuple(s: &str) -> Result<Vec<String>, String> {
    let mut res = Vec::new();
    let mut current = String::new();
    let mut depth_paren = 0;
    let mut depth_bracket = 0;
    for c in s.chars() {
        match c {
            '(' => { depth_paren+=1; current.push(c); },
            ')' => { depth_paren-=1; current.push(c); },
            '[' => { depth_bracket+=1; current.push(c); },
            ']' => { depth_bracket-=1; current.push(c); },
            ',' => {
                if depth_paren==0 && depth_bracket==0 {
                    res.push(current.trim().to_string());
                    current = String::new();
                } else {
                    current.push(c);
                }
            },
            _ => { current.push(c); }
        }
    }
    if !current.trim().is_empty() {
        res.push(current.trim().to_string());
    }
    Ok(res)
}

