mod keccak {
    // Pure Rust Keccak-f[1600] implementation
    // Based on public domain implementations

    const RC: [u64; 24] = [
        0x0000000000000001,
        0x0000000000008082,
        0x800000000000808a,
        0x8000000080008000,
        0x000000000000808b,
        0x0000000080000001,
        0x8000000080008081,
        0x8000000000008009,
        0x000000000000008a,
        0x0000000000000088,
        0x0000000080008009,
        0x000000008000000a,
        0x000000008000808b,
        0x800000000000008b,
        0x8000000000008089,
        0x8000000000008003,
        0x8000000000008002,
        0x8000000000000080,
        0x000000000000800a,
        0x800000008000000a,
        0x8000000080008081,
        0x8000000000008080,
        0x0000000080000001,
        0x8000000080008008,
    ];

    const R: [[u32;5];5] = [
        [0, 36, 3, 41, 18],
        [1, 44, 10, 45, 2],
        [62, 6, 43, 15, 61],
        [28, 55, 25, 21, 56],
        [27, 20, 39, 8, 14],
    ];

    fn rotl(x: u64, n: u32) -> u64 {
        (x << n) | (x >> (64 - n))
    }

    fn keccak_f(s: &mut [u64;25]) {
        for round in 0..24 {
            // Theta
            let mut c = [0u64;5];
            for x in 0..5 {
                c[x] = s[x] ^ s[x+5] ^ s[x+10] ^ s[x+15] ^ s[x+20];
            }
            let mut d = [0u64;5];
            for x in 0..5 {
                d[x] = c[(x+4)%5] ^ rotl(c[(x+1)%5], 1);
            }
            for x in 0..5 {
                for y in 0..5 {
                    let idx = x + 5*y;
                    s[idx] ^= d[x];
                }
            }
            // Rho Pi
            let mut b = [0u64;25];
            for x in 0..5 {
                for y in 0..5 {
                    let idx = x + 5*y;
                    let new_x = y;
                    let new_y = (2*x + 3*y) %5;
                    let new_idx = new_x + 5*new_y;
                    b[new_idx] = rotl(s[idx], R[x][y]);
                }
            }
            // Chi
            for x in 0..5 {
                for y in 0..5 {
                    let idx = x + 5*y;
                    let idx1 = ((x+1)%5) + 5*y;
                    let idx2 = ((x+2)%5) + 5*y;
                    s[idx] = b[idx] ^ ((!b[idx1]) & b[idx2]);
                }
            }
            // Iota
            s[0] ^= RC[round];
        }
    }

    pub fn keccak256(data: &[u8]) -> [u8;32] {
        // Keccak-256: rate 1088, capacity 512, suffix 0x01, output 32 bytes
        let rate = 136; // 1088 bits = 136 bytes
        let mut state = [0u64;25];
        let mut offset = 0;
        let mut block = [0u8; 136];

        let mut i = 0;
        while i < data.len() {
            let remaining = data.len() - i;
            let chunk = if remaining >= rate - offset {
                rate - offset
            } else {
                remaining
            };
            for j in 0..chunk {
                block[offset + j] ^= data[i + j];
            }
            offset += chunk;
            i += chunk;
            if offset == rate {
                // XOR block into state (little endian)
                for (j, chunk) in block.chunks(8).enumerate() {
                    let mut val = 0u64;
                    for (k, &b) in chunk.iter().enumerate() {
                        val |= (b as u64) << (8*k);
                    }
                    state[j] ^= val;
                }
                keccak_f(&mut state);
                offset = 0;
                block = [0u8;136];
            }
        }
        // Padding
        // pad10*1: suffix 0x01, then zeros, last byte 0x80
        block[offset] ^= 0x01;
        block[rate -1] ^= 0x80;
        for (j, chunk) in block.chunks(8).enumerate() {
            let mut val = 0u64;
            for (k, &b) in chunk.iter().enumerate() {
                val |= (b as u64) << (8*k);
            }
            state[j] ^= val;
        }
        keccak_f(&mut state);
        let mut out = [0u8;32];
        for (j, chunk) in out.chunks_mut(8).enumerate() {
            let val = state[j];
            for (k, b) in chunk.iter_mut().enumerate() {
                *b = ((val >> (8*k)) & 0xFF) as u8;
            }
        }
        out
    }
}

pub fn selector_for_function(func: &AbiFunction) -> [u8;4] {
    // canonical signature: name(type1,type2,...)
    // types are as displayed in type_str (already canonical? need to ensure tuples)
    // For function inputs, we need to use canonical representation: for tuples, "(type1,type2)"
    // We have inputs as AbiParam with type_str that may already be canonical. Use them.

    let mut sig = String::new();
    sig.push_str(&func.name);
    sig.push('(');
    for (i, inp) in func.inputs.iter().enumerate() {
        if i>0 { sig.push(','); }
        sig.push_str(&canonical_type(&inp.param_type));
    }
    sig.push(')');
    let hash = keccak256(sig.as_bytes());
    [hash[0], hash[1], hash[2], hash[3]]
}

fn canonical_type(pt: &ParamType) -> String {
    match pt {
        ParamType::Address => "address".to_string(),
        ParamType::Bool => "bool".to_string(),
        ParamType::String => "string".to_string(),
        ParamType::Bytes => "bytes".to_string(),
        ParamType::FixedBytes(n) => format!("bytes{}", n),
        ParamType::Uint(n) => format!("uint{}", n),
        ParamType::Int(n) => format!("int{}", n),
        ParamType::Array(inner) => format!("{}[]", canonical_type(inner)),
        ParamType::FixedArray(inner, len) => format!("{}[{}]", canonical_type(inner), len),
        ParamType::Tuple(types) => {
            let inner: Vec<String> = types.iter().map(|t| canonical_type(t)).collect();
            format!("({})", inner.join(","))
        }
    }
}

pub fn find_function<'a>(entries: &'a [AbiEntry], name_or_sig: &str) -> Result<&'a AbiFunction, String> {
    // If name_or_sig contains '(' then it's a signature
    if name_or_sig.contains('(') {
        // Parse signature
        // Signature format can be "func(inputs)" or "func(inputs):(outputs)" 
        // We need to parse name, inputs, outputs
        match parse_function_signature(name_or_sig) {
            Ok((name, input_types, output_types)) => {
                // Find function matching name, inputs, and outputs
                let mut candidates = Vec::new();
                for entry in entries {
                    if let AbiEntry::Function(f) = entry {
                        if f.name != name { continue; }
                        // Check inputs length
                        if f.inputs.len() != input_types.len() { continue; }
                        // Check each input type string equality via canonical?
                        let mut matches = true;
                        for (a,b) in f.inputs.iter().zip(input_types.iter()) {
                            // b is ParamType parsed from signature inputs
                            // Compare canonical
                            if canonical_type(&a.param_type) != canonical_type(b) {
                                matches = false;
                                break;
                            }
                        }
                        if !matches { continue; }
                        // Check outputs
                        if let Some(out_types) = &output_types {
                            // output_types is Some(vec) when signature includes output part
                            // For functions with empty outputs, signature should NOT include outputs (per observed behavior)
                            // If signature includes empty outputs "():()" that is invalid per earlier, but we treat as Some(empty vec) ??? Actually we reject empty outputs signature.
                            // Now compare
                            if f.outputs.len() != out_types.len() {
                                continue;
                            }
                            let mut m2 = true;
                            for (a,b) in f.outputs.iter().zip(out_types.iter()) {
                                if canonical_type(&a.param_type) != canonical_type(b) {
                                    m2=false;
                                    break;
                                }
                            }
                            if !m2 { continue; }
                        } else {
                            // Signature without outputs: should only match functions with empty outputs? Per observation, for functions with outputs non-empty, signature without outputs is invalid.
                            // So if output_types is None, we should only match if f.outputs is empty.
                            if !f.outputs.is_empty() {
                                // This should be considered invalid signature, not no match? Original returned invalid function signature error.
                                // But we need to differentiate: if there is a function with same name and inputs but has outputs, and signature omits outputs, it should be invalid signature, not just no match.
                                // So we need to handle that: if we find a function with matching name and inputs but outputs non-empty, and signature omits outputs, we should return invalid signature error.
                                // Similarly, if signature includes outputs but function has empty outputs, invalid.
                                // Let's check if any function matches inputs regardless of outputs, then we can return invalid signature.
                                // For now, skip this candidate and later handle invalid case.
                                continue;
                            }
                        }
                        candidates.push(f);
                    }
                }
                // If no candidates, check if there's a function with same name and inputs but mismatched outputs presence -> invalid signature
                if candidates.is_empty() {
                    // Look for any function with same name and inputs matching (ignoring outputs check)
                    for entry in entries {
                        if let AbiEntry::Function(f) = entry {
                            if f.name != name { continue; }
                            if f.inputs.len() != input_types.len() { continue; }
                            let mut matches = true;
                            for (a,b) in f.inputs.iter().zip(input_types.iter()) {
                                if canonical_type(&a.param_type) != canonical_type(b) {
                                    matches=false; break;
                                }
                            }
                            if matches {
                                // Found matching inputs, but outputs mismatched -> invalid signature
                                return Err(format!("invalid function signature `{}`", name_or_sig));
                            }
                        }
                    }
                    return Err(format!("Invalid name: {}", name_or_sig));
                }
                if candidates.len()>1 {
                    // More than one? Should not happen
                    return Err(format!("More than one function found for name `{}`, try providing the full signature", name));
                }
                Ok(candidates[0])
            },
            Err(e) => {
                // If parsing fails, return invalid signature error
                return Err(format!("invalid function signature `{}`", name_or_sig));
            }
        }
    } else {
        // Name lookup
        let mut candidates = Vec::new();
        for entry in entries {
            if let AbiEntry::Function(f) = entry {
                if f.name == name_or_sig {
                    if f.name == "constructor" {
                        // constructor is not a function
                        continue;
                    }
                    candidates.push(f);
                }
            }
        }
        if candidates.is_empty() {
            // Check if it's constructor name?
            if name_or_sig == "constructor" {
                return Err(format!("Invalid name: {}", name_or_sig));
            }
            return Err(format!("Invalid name: {}", name_or_sig));
        }
        if candidates.len()>1 {
            return Err(format!("More than one function found for name `{}`, try providing the full signature", name_or_sig));
        }
        Ok(candidates[0])
    }
}

fn parse_function_signature(sig: &str) -> Result<(String, Vec<ParamType>, Option<Vec<ParamType>>), String> {
    // Returns (name, inputs, outputs_opt)
    // outputs_opt None means no output part, Some(vec) means output part present (could be empty? but we will reject empty)
    // Example: "transfer(address,uint256):(bool)" -> name=transfer, inputs=[address,uint256], outputs=Some([bool])
    // "transfer(address,uint256)" -> inputs, outputs=None
    // "totalSupply():(uint256)" -> inputs=[], outputs=Some([uint256])
    // "rejectFork()" -> inputs=[], outputs=None
    // "foo(bool):()" -> outputs Some([]) but per spec this should be considered invalid signature, but we can parse and later reject
    // For validation: if outputs present and empty, we should return error for invalid signature? Actually spec: for functions with no outputs, signature with ":()" is invalid, so we should parse it but later treat as invalid.

    let sig = sig.trim();
    // Find '(' for inputs
    let open = sig.find('(').ok_or("no open")?;
    let close = find_matching_paren(sig, open)?;
    let name = sig[..open].trim();
    if name.is_empty() || name.contains(' ') {
        return Err(format!("Invalid name: {}", sig));
    }
    // Check name has no invalid chars? For simplicity, allow alphanumeric and _
    // But if name after trim contains spaces or other, we already handled.
    // Inputs substring
    let inputs_str = &sig[open+1..close];
    let input_types = if inputs_str.trim().is_empty() {
        vec![]
    } else {
        let parts = split_tuple(inputs_str)?;
        let mut vec = Vec::new();
        for p in parts {
            vec.push(parse_param_type(&p)?);
        }
        vec
    };
    let rest = sig[close+1..].trim();
    if rest.is_empty() {
        return Ok((name.to_string(), input_types, None));
    } else {
        // Should be ": (outputs)" or ":(outputs)"  ? There may be spaces? Original rejected spaces: "transfer(address, uint256)" invalid, so spaces are not allowed? Actually signature with space after comma was invalid. So we should be strict: rest must start with ':' and then '(' and ')'
        // Let's require rest starts with ':'
        if !rest.starts_with(':') {
            return Err("invalid".to_string());
        }
        let after_colon = rest[1..].trim();
        if !after_colon.starts_with('(') {
            return Err("invalid".to_string());
        }
        // Find matching paren for outputs
        let out_open = 0; // in after_colon
        let out_close = find_matching_paren(after_colon, out_open)?;
        let outputs_str = &after_colon[out_open+1..out_close];
        let output_types = if outputs_str.trim().is_empty() {
            vec![]
        } else {
            let parts = split_tuple(outputs_str)?;
            let mut vec = Vec::new();
            for p in parts {
                vec.push(parse_param_type(&p)?);
            }
            vec
        };
        let remaining = after_colon[out_close+1..].trim();
        if !remaining.is_empty() {
            return Err("invalid".to_string());
        }
        Ok((name.to_string(), input_types, Some(output_types)))
    }
}

fn find_matching_paren(s: &str, open_idx: usize) -> Result<usize, String> {
    let chars: Vec<char> = s.chars().collect();
    let mut depth = 0;
    for i in open_idx..chars.len() {
        match chars[i] {
            '(' => depth+=1,
            ')' => {
                depth-=1;
                if depth==0 {
                    return Ok(i);
                }
            },
            _ => {}
        }
    }
    Err("unmatched paren".to_string())
}

// Strict hex parsing helpers

pub fn parse_hex_strict(s: &str) -> Result<Vec<u8>, EthabiError> {
    let s = s.trim();
    let stripped = if s.starts_with("0x") || s.starts_with("0X") {
        &s[2..]
    } else {
        s
    };
    if stripped.is_empty() {
        return Ok(vec![]);
    }
    if stripped.len() %2 !=0 {
        return Err(EthabiError::HexOdd);
    }
    // Check for invalid chars and position
    for (i,c) in stripped.chars().enumerate() {
        if !c.is_ascii_hexdigit() {
            return Err(EthabiError::HexInvalidChar(c, i));
        }
    }
    hex::decode(stripped).map_err(|e| EthabiError::Msg(format!("Hex decode error: {}", e)))
}

