        for i in (0..32).rev() {
            out[i] = (val & 0xFF) as u8;
            val >>= 8;
            if val==0 { break; }
        }
        out
    }

    fn encode_token_list(tokens: &[Token]) -> (Vec<u8>, Vec<u8>) {
