        // else: size of static encoding (which may be multiple of 32)

        struct Item {
            is_dynamic: bool,
            head: Vec<u8>, // static encoding or offset placeholder
            tail: Vec<u8>,
            head_size: usize,
        }

        let mut items: Vec<Item> = Vec::new();
        for tok in tokens {
            let dyn_ = is_dynamic(tok);
            if dyn_ {
                let tail = encode_dynamic_data(tok);
                items.push(Item {
                    is_dynamic: true,
                    head: vec![0u8;32], // placeholder for offset
                    tail,
                    head_size: 32,
                });
            } else {
                let head = encode_static_token(tok);
                let sz = head.len();
                items.push(Item {
                    is_dynamic: false,
                    head,
                    tail: vec![],
                    head_size: sz,
                });
            }
        }

        let total_head_size: usize = items.iter().map(|it| it.head_size).sum();
        let mut heads = Vec::with_capacity(total_head_size);
        let mut tails = Vec::new();
        let mut offset = total_head_size;

        for item in items {
            if item.is_dynamic {
                // head is offset
                let off_bytes = encode_uint(offset);
                heads.extend_from_slice(&off_bytes);
                offset += item.tail.len();
                tails.extend(item.tail);
            } else {
                heads.extend(item.head);
            }
        }
        (heads, tails)
    }

    // Now encode the top-level list
    let (heads, tails) = encode_token_list(tokens);
    let mut out = Vec::new();
    out.extend(heads);
    out.extend(tails);
    (out.clone(), vec![])
