// Decoding

pub fn decode_tokens(param_types: &[ParamType], data: &[u8]) -> Result<Vec<Token>, String> {
    // Decode according to ABI spec
    // Use recursive decoding with offsets

    fn is_dynamic_type(pt: &ParamType) -> bool {
        match pt {
            ParamType::String => true,
            ParamType::Bytes => true,
            ParamType::Array(_) => true,
            ParamType::FixedArray(inner, _) => is_dynamic_type(inner),
            ParamType::Tuple(types) => types.iter().any(|t| is_dynamic_type(t)),
            _ => false,
        }
    }

    fn decode_one(pt: &ParamType, data: &[u8], offset: usize) -> Result<(Token, usize), String> {
        // offset is position in original data where this param's static part starts?
        // For simplicity, we will decode based on data slice starting at offset, but for dynamic types, we need to read offset pointer then decode from that position.

        // Returns (token, next_offset) where next_offset is offset+32 for static? Actually for decoding list, we need to know how many bytes consumed in head.

        // We'll treat data as full blob, and offset is current head position.

        if data.len() < offset + 32 {
            return Err("Invalid data".to_string());
        }
        if is_dynamic_type(pt) {
            // Read offset (u256)
            let off_bytes = &data[offset..offset+32];
            let off = u256_to_usize(off_bytes)?;
            if off >= data.len() {
                return Err("Invalid data".to_string());
            }
            // Decode actual token from data[off..]
            let token = decode_at(pt, data, off)?;
            Ok((token, offset+32))
        } else {
            // Static
            let token = decode_at(pt, data, offset)?;
            // For static types that occupy multiple words (fixed array, tuple), the size may be >32
            let size = static_size(pt);
            Ok((token, offset+size))
        }
    }

    fn static_size(pt: &ParamType) -> usize {
        match pt {
            ParamType::Tuple(types) => {
                // If tuple is static, its size is sum of static sizes of members (each may be multiple words if fixed array)
                // But if tuple is dynamic, it would have been handled as dynamic (offset)
                // So here we assume static tuple
                let mut sz=0;
                for t in types {
                    sz+=static_size(t);
                }
                sz
            },
            ParamType::FixedArray(inner, len) => {
                // If inner is dynamic, this fixed array would be dynamic, not static
                // So for static case, inner static
                static_size(inner) * len
            },
            _ => 32,
        }
    }

    fn decode_at(pt: &ParamType, data: &[u8], at: usize) -> Result<Token, String> {
        match pt {
            ParamType::Address => {
                if data.len() < at+32 { return Err("Invalid data".to_string()); }
                let word = &data[at..at+32];
                // Last 20 bytes are address
                let mut addr = [0u8;20];
                addr.copy_from_slice(&word[12..]);
                Ok(Token::Address(addr))
            },
            ParamType::Bool => {
                if data.len() < at+32 { return Err("Invalid data".to_string()); }
                let word = &data[at..at+32];
                // Must be 0 or 1
