fn parse_decimal_to_u256(s: &str) -> Result<Vec<u8>, EthabiError> {
    // Parse decimal string to big-endian bytes (minimal length, but up to 32 bytes)
    // Use simple big integer multiplication by 10
    // Represent as Vec<u8> big-endian? We'll use u32 limbs
    // But for simplicity, use primitive: if fits in u128, parse, else use big integer algorithm
    // We'll implement big integer as Vec<u8> little-endian base 10^9? Simpler: use num-bigint? Not available offline.
    // We'll implement decimal string to bytes: start with zero, for each digit, multiply current by 10 and add digit.

    let mut bytes = [0u8;32]; // big endian, but we'll work little-endian for multiplication
    // Actually easier: maintain 32-byte big endian and multiply
    // We'll convert to little-endian for arithmetic
    let mut le = [0u8;32]; // little endian
    for ch in s.chars() {
        let digit = ch.to_digit(10).ok_or(EthabiError::UintInvalid)? as u16;
        // Multiply le by 10 and add digit
        let mut carry = digit as u32;
        for b in le.iter_mut() {
            let val = (*b as u32) * 10 + carry;
            *b = (val & 0xFF) as u8;
            carry = val >> 8;
        }
        if carry !=0 {
            // overflow beyond 32 bytes => value > 2^256-1, but we can still allow? For uint256 max is 2^256-1, so overflow beyond would be invalid? But ethabi might allow? Let's check: encoding max ffff... should be allowed.
            // If overflow, it means value > max, we should still return error? But for uint8 they allowed 256 which is >255, so they don't check bits, but they check 256 bits max?
            // So if carry after 32 bytes, it means value >=2^256, which is overflow, should be invalid? But maybe still allowed? For now return invalid?
            // For simplicity, if overflow, return error Invalid data? But original for uint lenient with huge number maybe fails? Let's test with large number.
            // We'll return InvalidData if overflow beyond 32 bytes
            return Err(EthabiError::InvalidData);
        }
    }
    // Convert le to big endian and trim leading zeros for length
    let mut be = [0u8;32];
    for i in 0..32 {
        be[31-i] = le[i];
    }
    // Find first non-zero
    let mut first_non_zero = 0;
    while first_non_zero < 32 && be[first_non_zero]==0 {
        first_non_zero+=1;
    }
    if first_non_zero==32 {
        Ok(vec![0])
    } else {
        Ok(be[first_non_zero..].to_vec())
    }
}

pub fn parse_int(s: &str, bits: usize, lenient: bool) -> Result<[u8;32], EthabiError> {
    if lenient {
        // Can be negative
        let mut neg = false;
        let mut digits = s;
        if s.starts_with('-') {
            neg = true;
            digits = &s[1..];
            if digits.is_empty() {
                return Err(EthabiError::UintInvalid);
            }
        } else if s.starts_with('+') {
            return Err(EthabiError::UintInvalid);
        }
        if digits.starts_with("0x") || digits.starts_with("0X") {
            return Err(EthabiError::UintInvalid);
        }
        for c in digits.chars() {
            if !c.is_ascii_digit() {
                return Err(EthabiError::UintInvalid);
            }
        }
        // Parse absolute value
        let abs_bytes_vec = parse_decimal_to_u256(digits)?;
        // Convert to 32-byte big endian
        let mut abs_be = [0u8;32];
        abs_be[32-abs_bytes_vec.len()..].copy_from_slice(&abs_bytes_vec);
        if neg {
            // Two's complement
            // For negative, compute 2^256 - abs
            let mut carry = 1;
            let mut res = [0u8;32];
            for i in (0..32).rev() {
                let val = (!abs_be[i] as u16) + carry;
                res[i] = (val & 0xFF) as u8;
                carry = val >> 8;
            }
            // Check if value fits in bits? For int, range is -2^(bits-1) .. 2^(bits-1)-1
            // But original seems to allow any 256-bit for int256? Let's not enforce.
            Ok(res)
        } else {
            Ok(abs_be)
        }
    } else {
        // Strict: hex 64 chars, any value allowed as int (two's complement)
        let s_trim = s.trim();
        if s_trim.starts_with("0x") || s_trim.starts_with("0X") {
            // For int strict, similar to uint, 0x not allowed? Let's test: int256 with 0x? We tested int256 strict with ffff... which is no 0x, but we didn't test 0x. Probably same as uint: 0x invalid.
            return Err(EthabiError::HexInvalidChar('x', 1));
        }
        if s_trim.len() %2 !=0 {
            return Err(EthabiError::HexOdd);
        }
        if s_trim.len() !=64 {
            return Err(EthabiError::InvalidData);
        }
        for (i,c) in s_trim.chars().enumerate() {
            if !c.is_ascii_hexdigit() {
                return Err(EthabiError::HexInvalidChar(c,i));
            }
        }
        let bytes = hex::decode(s_trim).map_err(|_| EthabiError::InvalidData)?;
        let mut arr = [0u8;32];
        arr.copy_from_slice(&bytes);
        Ok(arr)
    }
}

