        }
    }
    let bytes = hex::decode(stripped).map_err(|_| EthabiError::InvalidData)?;
    Ok(bytes)
}

pub fn parse_bytes(s: &str, _lenient: bool) -> Result<Vec<u8>, EthabiError> {
    // Dynamic bytes: hex string, optionally 0x, any even length, empty allowed
    let s_trim = s.trim();
    if s_trim.is_empty() {
        return Ok(vec![]);
    }
    let stripped = if s_trim.starts_with("0x") || s_trim.starts_with("0X") {
        &s_trim[2..]
    } else {
        s_trim
    };
    if stripped.is_empty() {
        return Ok(vec![]);
    }
    if stripped.len() %2 !=0 {
        return Err(EthabiError::HexOdd);
    }
    for (i,c) in stripped.chars().enumerate() {
        if !c.is_ascii_hexdigit() {
            return Err(EthabiError::HexInvalidChar(c,i));
        }
    }
    let bytes = hex::decode(stripped).map_err(|_| EthabiError::InvalidData)?;
    Ok(bytes)
}

// Parsing of param values (for encode)

pub fn parse_token_value(type_: &ParamType, value_str: &str, lenient: bool) -> Result<Token, EthabiError> {
    match type_ {
        ParamType::Bool => {
            let b = parse_bool(value_str, lenient)?;
            Ok(Token::Bool(b))
        },
        ParamType::Uint(bits) => {
            let bytes = parse_uint(value_str, *bits, lenient)?;
            Ok(Token::Uint(bytes))
        },
        ParamType::Int(bits) => {
            let bytes = parse_int(value_str, *bits, lenient)?;
            Ok(Token::Int(bytes))
        },
        ParamType::Address => {
            let addr = parse_address(value_str, lenient)?;
            Ok(Token::Address(addr))
        },
        ParamType::FixedBytes(n) => {
            let bytes = parse_fixed_bytes(value_str, *n, lenient)?;
            Ok(Token::FixedBytes(bytes))
        },
        ParamType::Bytes => {
            let bytes = parse_bytes(value_str, lenient)?;
            Ok(Token::Bytes(bytes))
        },
        ParamType::String => {
            // String value is taken as is, no hex parsing
            // But need to handle lenient? Same
            Ok(Token::String(value_str.to_string()))
        },
        ParamType::Array(inner) => {
            // value_str should be like "[1,2,3]" or "[]"
            let trimmed = value_str.trim();
            if !trimmed.starts_with('[') || !trimmed.ends_with(']') {
                return Err(EthabiError::InvalidData);
            }
            let inner_str = &trimmed[1..trimmed.len()-1];
            if inner_str.trim().is_empty() {
                return Ok(Token::Array(vec![]));
            }
            let elements = split_array_elements(inner_str)?;
            let mut tokens = Vec::new();
            for el in elements {
                tokens.push(parse_token_value(inner, &el, lenient)?);
            }
            Ok(Token::Array(tokens))
        },
        ParamType::FixedArray(inner, len) => {
            let trimmed = value_str.trim();
            if !trimmed.starts_with('[') || !trimmed.ends_with(']') {
                return Err(EthabiError::InvalidData);
            }
            let inner_str = &trimmed[1..trimmed.len()-1];
            if inner_str.trim().is_empty() {
                if *len==0 {
                    return Ok(Token::FixedArray(vec![]));
                } else {
                    // Empty array for non-zero fixed length? Should be invalid? But let's allow empty only if len==0
                    // For len>0, empty should be invalid? Original: fixed array with empty "[]" - what happens? Let's test: address[2] with [] maybe invalid? We didn't test.
                    // We'll require length match
                    if *len==0 {
                        return Ok(Token::FixedArray(vec![]));
                    } else {
                        return Err(EthabiError::InvalidData);
                    }
                }
            }
            let elements = split_array_elements(inner_str)?;
            if elements.len() != *len {
                // For fixed array, length must match
                // Original behavior: if you give [1,2] for address[2] it works, if you give [1] maybe invalid? Let's assume invalid data if mismatch
                // But we should check: for address[2] with [1,2] lenient short failed odd, but length 2 is correct. So length check is separate from value parsing.
                // If length mismatch, it's invalid data? Let's return InvalidData
                return Err(EthabiError::InvalidData);
            }
            let mut tokens = Vec::new();
            for el in elements {
                tokens.push(parse_token_value(inner, &el, lenient)?);
            }
            Ok(Token::FixedArray(tokens))
        },
        ParamType::Tuple(types) => {
            // value_str like "(true,1)" or "(1,2)"
            let trimmed = value_str.trim();
            if !trimmed.starts_with('(') || !trimmed.ends_with(')') {
                return Err(EthabiError::InvalidData);
            }
            let inner_str = &trimmed[1..trimmed.len()-1];
            let elements = if inner_str.trim().is_empty() {
                vec![]
            } else {
                split_tuple(inner_str)?
            };
            if elements.len() != types.len() {
                return Err(EthabiError::InvalidData);
            }
            let mut tokens = Vec::new();
            for (t, v) in types.iter().zip(elements.iter()) {
                tokens.push(parse_token_value(t, v, lenient)?);
            }
            Ok(Token::Tuple(tokens))
        }
    }
}

fn split_array_elements(s: &str) -> Result<Vec<String>, EthabiError> {
    // Split by commas respecting nested brackets and parens and quotes?
    // For simplicity, we need to handle nested arrays and tuples, and strings that may contain commas? Strings are simple no commas? But could contain?
    // We'll parse with depth counters for [], (), and also handle quotes for strings? Original string array with ["hello","world"] includes quotes and commas inside brackets but quoted strings themselves may contain commas? We ignore.

    let mut res = Vec::new();
    let mut current = String::new();
    let mut depth_bracket = 0;
    let mut depth_paren = 0;
    let mut in_quotes = false;
    let mut quote_char = '"';
    let chars: Vec<char> = s.chars().collect();
    let mut i=0;
    while i<chars.len() {
        let c = chars[i];
        if in_quotes {
            current.push(c);
            if c == quote_char {
                // Check if escaped?
                in_quotes = false;
            }
            i+=1;
            continue;
        }
        match c {
            '"' | '\'' => {
                in_quotes = true;
                quote_char = c;
                current.push(c);
            },
            '[' => { depth_bracket+=1; current.push(c); },
            ']' => { depth_bracket-=1; current.push(c); },
            '(' => { depth_paren+=1; current.push(c); },
            ')' => { depth_paren-=1; current.push(c); },
            ',' => {
                if depth_bracket==0 && depth_paren==0 {
                    res.push(current.trim().to_string());
                    current = String::new();
                } else {
                    current.push(c);
                }
            },
            _ => { current.push(c); }
        }
        i+=1;
    }
    if !current.trim().is_empty() {
        res.push(current.trim().to_string());
    }
    // For each element, trim and also remove surrounding quotes? For string types, the value may be with quotes like "\"hello\"" - need to handle?
    // In our earlier tests, string array with ["hello","world"] the elements after split are "\"hello\"" and "\"world\"" including quotes.
    // But for string param, the value itself is "hello" without quotes. However inside array, they include quotes to represent string.
    // Original behavior: encode params -v string[] '["hello","world"]' succeeded and the quoted strings were treated as strings? How?
    // In that case, the array elements are "\"hello\"" (with quotes). We need to strip quotes for string token.

    // We'll handle stripping quotes for string detection in parse_token_value for String type: if value_str is wrapped in quotes, remove them.

    Ok(res)
}

