            eprintln!();
            eprintln!("For more information try --help");
            std::process::exit(1);
        } else {
            if abi_path.is_none() {
                abi_path=Some(a.to_string());
            } else if event_name.is_none() {
                event_name=Some(a.to_string());
            } else if data.is_none() {
                data=Some(a.to_string());
            } else {
                eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context", a);
                eprintln!();
                eprintln!("USAGE:");
                eprintln!("    {} decode log [OPTIONS] <abi-path> <event-name-or-signature> <data>", prog);
                eprintln!();
                eprintln!("For more information try --help");
                std::process::exit(1);
            }
            i+=1;
        }
    }
    if abi_path.is_none() || event_name.is_none() || data.is_none() {
        eprintln!("error: The following required arguments were not provided:");
        if abi_path.is_none() { eprintln!("    <abi-path>"); }
        if event_name.is_none() { eprintln!("    <event-name-or-signature>"); }
        if data.is_none() { eprintln!("    <data>"); }
        eprintln!();
        eprintln!("USAGE:");
        eprintln!("    {} decode log <abi-path> <event-name-or-signature> <data> -l <topic>...", prog);
        eprintln!();
        eprintln!("For more information try --help");
        std::process::exit(1);
    }
    match crate::ethabi_impl::decode_log_wrapper(&abi_path.unwrap(), &event_name.unwrap(), &data.unwrap(), &topics) {
        Ok(lines) => { for l in lines { println!("{}", l); } },
        Err(e) => { eprintln!("Error: {}", e); std::process::exit(1); }
    }
}
