            if sub2=="params" { print_decode_params_help(&args[0]); return; }
            if sub2=="log" { print_decode_log_help(&args[0]); return; }
        }
        print_decode_help(&args[0]);
        return;
    }
    if sub=="-V" || sub=="--version" {
        println!("executable-decode 18.0.0");
        return;
    }
    match sub {
        "function" => handle_decode_function(args),
        "params" => handle_decode_params(args),
        "log" => handle_decode_log(args),
        _ => {
            eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context", sub);
            eprintln!();
            eprintln!("USAGE:");
            eprintln!("    {} decode <SUBCOMMAND>", args[0]);
            eprintln!();
            eprintln!("For more information try --help");
            std::process::exit(1);
        }
    }
}

