fn handle_decode_params(args: &[String]) {
    let prog=&args[0];
    let all: Vec<String>=args.iter().skip(3).cloned().collect();
    if all.is_empty() {
        eprintln!("error: The following required arguments were not provided:");
        eprintln!("    <data>");
        eprintln!();
        eprintln!("USAGE:");
        eprintln!("    {} decode params <data> -t <type>...", prog);
        eprintln!();
        eprintln!("For more information try --help");
        std::process::exit(1);
    }
    // Check for help/version
    for a in &all {
        if a=="-h" || a=="--help" {
            print_decode_params_help(prog);
            return;
        }
        if a=="-V" || a=="--version" {
            println!("executable-decode-params 18.0.0");
            return;
        }
    }
    // Data is last arg if not starting with "-" and not being a type after -t?
    // We'll parse: iterate, collecting types for each -t, and data as last positional.
    let mut types: Vec<String> = Vec::new();
    let mut data: Option<String> = None;
    let mut i=0;
    while i<all.len() {
        let a=&all[i];
        if a=="-t" {
            i+=1;
            if i>=all.len() {
                eprintln!("error: The argument '-t <type>...' requires a value but none was supplied");
                eprintln!();
                eprintln!("USAGE:");
                eprintln!("    {} decode params -t <type>... <data>", prog);
                eprintln!();
                eprintln!("For more information try --help");
                std::process::exit(1);
            }
            // Consume following args that are not flags, but leave last one as data if it's the only remaining?
            // We will consume until next flag or until only one arg left that will be data.
            while i<all.len() {
                let nxt=&all[i];
                if nxt.starts_with("-") {
                    break;
                }
                // If this is last element, it should be data, not type
                if i==all.len()-1 {
                    // last element is data
                    break;
                }
                types.push(nxt.clone());
                i+=1;
            }
        } else if a.starts_with("-") {
            eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context", a);
            eprintln!();
            eprintln!("USAGE:");
            eprintln!("    {} decode params [OPTIONS] <data>", prog);
            eprintln!();
            eprintln!("For more information try --help");
            std::process::exit(1);
        } else {
            // Positional
            if i==all.len()-1 {
                data=Some(a.clone());
                i+=1;
            } else {
                eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context", a);
                eprintln!();
                eprintln!("USAGE:");
                eprintln!("    {} decode params [OPTIONS] <data>", prog);
                eprintln!();
                eprintln!("For more information try --help");
                std::process::exit(1);
            }
        }
    }
    if data.is_none() {
        eprintln!("error: The following required arguments were not provided:");
        eprintln!("    <data>");
        eprintln!();
        eprintln!("USAGE:");
        eprintln!("    {} decode params <data> -t <type>...", prog);
        eprintln!();
        eprintln!("For more information try --help");
        std::process::exit(1);
    }
    // If data still None but all contains only types and missing data, handle
    match crate::ethabi_impl::decode_params_wrapper(&types, &data.unwrap()) {
        Ok(lines) => { for l in lines { println!("{}", l); } },
        Err(e) => { eprintln!("Error: {}", e); std::process::exit(1); }
    }
}

