impl std::fmt::Display for EthabiError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            EthabiError::Msg(s) => write!(f, "{}", s),
            EthabiError::HexOdd => write!(f, "Hex parsing error: Odd number of digits\n\nCaused by:\n    Odd number of digits"),
            EthabiError::HexInvalidChar(c, pos) => write!(f, "Hex parsing error: Invalid character '{}' at position {}\n\nCaused by:\n    Invalid character '{}' at position {}", c, pos, c, pos),
            EthabiError::UintInvalid => write!(f, "Uint parse error: InvalidCharacter"),
            EthabiError::InvalidData => write!(f, "Invalid data"),
