                if depth_bracket==0 && depth_paren==0 {
                    res.push(current.trim().to_string());
                    current = String::new();
                } else { current.push(c); }
            },
            _ => { current.push(c); }
        }
        i+=1;
    }
    if !current.trim().is_empty() { res.push(current.trim().to_string()); }
    res
}
