                        if f.name != name { continue; }
                        if f.inputs.len() != input_types.len() { continue; }
                        let mut matches = true;
                        for (a,b) in f.inputs.iter().zip(input_types.iter()) {
                            if canonical_type(&a.param_type) != canonical_type(b) { matches = false; break; }
                        }
                        if !matches { continue; }
                        if let Some(out_types) = &output_types {
                            if f.outputs.len() != out_types.len() { continue; }
                            let mut m2 = true;
                            for (a,b) in f.outputs.iter().zip(out_types.iter()) {
                                if canonical_type(&a.param_type) != canonical_type(b) { m2=false; break; }
                            }
                            if !m2 { continue; }
                        } else {
                            if !f.outputs.is_empty() { continue; }
                        }
