                            if f.name != name { continue; }
                            if f.inputs.len() != input_types.len() { continue; }
                            let mut matches = true;
                            for (a,b) in f.inputs.iter().zip(input_types.iter()) {
                                if canonical_type(&a.param_type) != canonical_type(b) { matches=false; break; }
                            }
                            if matches {
                                return Err(format!("invalid function signature `{}`", name_or_sig));
                            }
                        }
                    }
                    return Err(format!("Invalid name: {}", name_or_sig));
                }
                if candidates.len()>1 {
                    return Err(format!("More than one function found for name `{}`, try providing the full signature", name));
                }
                Ok(candidates[0])
            },
            Err(_) => Err(format!("invalid function signature `{}`", name_or_sig)),
        }
    } else {
        let mut candidates = Vec::new();
        for entry in entries {
            if let AbiEntry::Function(f) = entry {
                if f.name == name_or_sig {
                    if f.name == "constructor" { continue; }
                    candidates.push(f);
                }
            }
        }
        if candidates.is_empty() {
            return Err(format!("Invalid name: {}", name_or_sig));
        }
        if candidates.len()>1 {
            return Err(format!("More than one function found for name `{}`, try providing the full signature", name_or_sig));
        }
        Ok(candidates[0])
    }
}

pub fn find_event<'a>(entries: &'a [AbiEntry], name_or_sig: &str) -> Result<&'a AbiEvent, String> {
    if name_or_sig.contains('(') {
        let (name, input_types, _output_types) = match parse_function_signature_event(name_or_sig) {
            Ok(v) => v,
            Err(_) => {
                return Err(format!("Invalid signature `{}`", abbreviate_sig(name_or_sig)));
            }
        };
        for entry in entries {
            if let AbiEntry::Event(ev) = entry {
                if ev.name != name { continue; }
                if ev.inputs.len() != input_types.len() { continue; }
                let mut matches = true;
                for (a,b) in ev.inputs.iter().zip(input_types.iter()) {
                    if canonical_type(&a.param_type) != canonical_type(b) { matches=false; break; }
                }
                if matches { return Ok(ev); }
            }
        }
        for entry in entries {
            if let AbiEntry::Event(ev) = entry {
                if ev.name == name {
                    return Err(format!("Invalid signature `{}`", abbreviate_sig(name_or_sig)));
                }
            }
        }
        return Err(format!("Invalid name: {}", name));
    } else {
        let mut candidates = Vec::new();
        for entry in entries {
            if let AbiEntry::Event(e) = entry {
                if e.name == name_or_sig { candidates.push(e); }
            }
        }
        if candidates.is_empty() {
            return Err(format!("Invalid name: {}", name_or_sig));
        }
        if candidates.len()>1 {
            return Err(format!("More than one function found for name `{}`, try providing the full signature", name_or_sig));
        }
        Ok(candidates[0])
    }
}

fn abbreviate_sig(sig: &str) -> String {
    let hash = keccak256(sig.as_bytes());
    let first = hex::encode(&hash[0..2]);
    let last = hex::encode(&hash[30..32]);
    format!("0x{}…{}", first, last)
}

fn parse_function_signature(sig: &str) -> Result<(String, Vec<ParamType>, Option<Vec<ParamType>>), String> {
    let sig = sig.trim();
    let open = sig.find('(').ok_or("no open")?;
    let close = find_matching_paren(sig, open)?;
    let name = sig[..open].trim();
    if name.is_empty() || name.contains(' ') { return Err("invalid".to_string()); }
    let inputs_str = &sig[open+1..close];
    let input_types = if inputs_str.trim().is_empty() {
        vec![]
    } else {
        if inputs_str.contains(' ') { return Err("invalid".to_string()); }
        let parts = split_tuple_string(inputs_str)?;
        let mut vec = Vec::new();
        for p in parts {
            if p.contains(' ') { return Err("invalid".to_string()); }
            vec.push(parse_param_type(&p).map_err(|_| "invalid".to_string())?);
        }
        vec
    };
    let rest = sig[close+1..].trim();
    if rest.is_empty() {
        return Ok((name.to_string(), input_types, None));
    } else {
        if !rest.starts_with(':') { return Err("invalid".to_string()); }
        let after_colon = rest[1..].trim();
        if !after_colon.starts_with('(') { return Err("invalid".to_string()); }
        let out_close = find_matching_paren(after_colon, 0)?;
        let outputs_str = &after_colon[1..out_close];
        if outputs_str.trim().is_empty() {
            return Err("invalid".to_string());
        }
        if outputs_str.contains(' ') { return Err("invalid".to_string()); }
        let parts = split_tuple_string(outputs_str)?;
        let mut vec = Vec::new();
        for p in parts {
            if p.contains(' ') { return Err("invalid".to_string()); }
            vec.push(parse_param_type(&p).map_err(|_| "invalid".to_string())?);
        }
        let remaining = after_colon[out_close+1..].trim();
        if !remaining.is_empty() { return Err("invalid".to_string()); }
        Ok((name.to_string(), input_types, Some(vec)))
    }
}

fn parse_function_signature_event(sig: &str) -> Result<(String, Vec<ParamType>, Option<Vec<ParamType>>), String> {
    let sig = sig.trim();
    let open = sig.find('(').ok_or("no open")?;
    let close = find_matching_paren(sig, open)?;
    let name = sig[..open].trim();
    if name.is_empty() || name.contains(' ') { return Err("invalid".to_string()); }
    let inputs_str = &sig[open+1..close];
    let input_types = if inputs_str.trim().is_empty() {
        vec![]
    } else {
        if inputs_str.contains(' ') { return Err("invalid".to_string()); }
        let parts = split_tuple_string(inputs_str)?;
        let mut vec = Vec::new();
        for p in parts {
            if p.contains(' ') { return Err("invalid".to_string()); }
            vec.push(parse_param_type(&p).map_err(|_| "invalid".to_string())?);
        }
        vec
    };
    let rest = sig[close+1..].trim();
    if rest.is_empty() {
        Ok((name.to_string(), input_types, None))
    } else {
        if !rest.starts_with(':') { return Err("invalid".to_string()); }
        let after_colon = rest[1..].trim();
        if !after_colon.starts_with('(') { return Err("invalid".to_string()); }
        let out_close = find_matching_paren(after_colon, 0)?;
        let outputs_str = &after_colon[1..out_close];
        let output_types = if outputs_str.trim().is_empty() {
            vec![]
        } else {
            if outputs_str.contains(' ') { return Err("invalid".to_string()); }
            let parts = split_tuple_string(outputs_str)?;
            let mut vec = Vec::new();
            for p in parts {
                if p.contains(' ') { return Err("invalid".to_string()); }
                vec.push(parse_param_type(&p).map_err(|_| "invalid".to_string())?);
            }
            vec
        };
        let remaining = after_colon[out_close+1..].trim();
        if !remaining.is_empty() { return Err("invalid".to_string()); }
        Ok((name.to_string(), input_types, Some(output_types)))
    }
}

fn find_matching_paren(s: &str, open_idx: usize) -> Result<usize, String> {
    let chars: Vec<char> = s.chars().collect();
    let mut depth = 0;
    for i in open_idx..chars.len() {
        match chars[i] {
            '(' => depth+=1,
            ')' => { depth-=1; if depth==0 { return Ok(i); } },
            _ => {}
        }
    }
    Err("unmatched paren".to_string())
}

pub fn parse_hex_strict(s: &str) -> Result<Vec<u8>, EthabiError> {
    let s = s.trim();
    if s.is_empty() { return Ok(vec![]); }
    if s == "0x" { return Ok(vec![]); }
    let stripped = if s.starts_with("0x") || s.starts_with("0X") { &s[2..] } else { s };
    if stripped.is_empty() { return Ok(vec![]); }
    if stripped.len() %2 !=0 { return Err(EthabiError::HexOdd); }
    for (i,c) in stripped.chars().enumerate() {
        if !c.is_ascii_hexdigit() { return Err(EthabiError::HexInvalidChar(c, i)); }
    }
    hex::decode(stripped).map_err(|_| EthabiError::InvalidData)
}

pub fn parse_address(s: &str, _lenient: bool) -> Result<[u8;20], EthabiError> {
    let s_trim = s.trim();
    let stripped = if s_trim.starts_with("0x") || s_trim.starts_with("0X") { &s_trim[2..] } else { s_trim };
    if stripped.len() != 40 { return Err(EthabiError::InvalidData); }
    for (i,c) in stripped.chars().enumerate() {
        if !c.is_ascii_hexdigit() { return Err(EthabiError::HexInvalidChar(c, i)); }
    }
    let bytes = hex::decode(stripped).map_err(|_| EthabiError::InvalidData)?;
    let mut arr = [0u8;20];
    arr.copy_from_slice(&bytes);
    Ok(arr)
}

pub fn parse_bool(s: &str, _lenient: bool) -> Result<bool, EthabiError> {
    match s {
        "1" | "true" => Ok(true),
        "0" | "false" => Ok(false),
        _ => Err(EthabiError::InvalidData),
    }
}

pub fn parse_uint(s: &str, _bits: usize, lenient: bool) -> Result<[u8;32], EthabiError> {
    if lenient {
        if s.starts_with("0x") || s.starts_with("0X") { return Err(EthabiError::UintInvalid); }
        if s.is_empty() { return Err(EthabiError::UintInvalid); }
        for c in s.chars() { if !c.is_ascii_digit() { return Err(EthabiError::UintInvalid); } }
        let val = parse_decimal_to_u256(s)?;
        let mut bytes = [0u8;32];
        if val.len() <=32 { bytes[32 - val.len()..].copy_from_slice(&val); } else { return Err(EthabiError::InvalidData); }
        Ok(bytes)
    } else {
        let s_trim = s.trim();
        if s_trim.len() %2 !=0 { return Err(EthabiError::HexOdd); }
        if s_trim.starts_with("0x") || s_trim.starts_with("0X") { return Err(EthabiError::HexInvalidChar('x', 1)); }
        if s_trim.len() != 64 { return Err(EthabiError::InvalidData); }
        for (i,c) in s_trim.chars().enumerate() {
            if !c.is_ascii_hexdigit() { return Err(EthabiError::HexInvalidChar(c, i)); }
        }
        let bytes = hex::decode(s_trim).map_err(|_| EthabiError::InvalidData)?;
        let mut arr = [0u8;32];
        arr.copy_from_slice(&bytes);
        Ok(arr)
    }
}

fn parse_decimal_to_u256(s: &str) -> Result<Vec<u8>, EthabiError> {
    let mut le = [0u8;32];
    for ch in s.chars() {
        let digit = ch.to_digit(10).ok_or(EthabiError::UintInvalid)? as u32;
        let mut carry = digit;
        for b in le.iter_mut() {
            let val = (*b as u32) * 10 + carry;
            *b = (val & 0xFF) as u8;
            carry = val >> 8;
        }
        if carry !=0 { return Err(EthabiError::InvalidData); }
    }
    let mut be = [0u8;32];
    for i in 0..32 { be[31-i] = le[i]; }
    let mut first_non_zero = 0;
    while first_non_zero < 32 && be[first_non_zero]==0 { first_non_zero+=1; }
    if first_non_zero==32 { Ok(vec![0]) } else { Ok(be[first_non_zero..].to_vec()) }
}

pub fn parse_int(s: &str, _bits: usize, lenient: bool) -> Result<[u8;32], EthabiError> {
    if lenient {
        let mut neg = false;
        let mut digits = s;
        if s.starts_with('-') {
            neg = true;
            digits = &s[1..];
            if digits.is_empty() { return Err(EthabiError::UintInvalid); }
        } else if s.starts_with('+') {
            return Err(EthabiError::UintInvalid);
        }
        if digits.starts_with("0x") || digits.starts_with("0X") { return Err(EthabiError::UintInvalid); }
        for c in digits.chars() { if !c.is_ascii_digit() { return Err(EthabiError::UintInvalid); } }
        let abs_bytes_vec = parse_decimal_to_u256(digits)?;
        let mut abs_be = [0u8;32];
        if abs_bytes_vec.len() <=32 { abs_be[32-abs_bytes_vec.len()..].copy_from_slice(&abs_bytes_vec); } else { return Err(EthabiError::InvalidData); }
        if neg {
            let mut carry = 1;
            let mut res = [0u8;32];
            for i in (0..32).rev() {
                let val = (!abs_be[i] as u16) + carry;
                res[i] = (val & 0xFF) as u8;
                carry = val >> 8;
            }
            Ok(res)
        } else {
            Ok(abs_be)
        }
    } else {
        let s_trim = s.trim();
        if s_trim.len() %2 !=0 { return Err(EthabiError::HexOdd); }
        if s_trim.starts_with("0x") || s_trim.starts_with("0X") { return Err(EthabiError::HexInvalidChar('x', 1)); }
        if s_trim.len() !=64 { return Err(EthabiError::InvalidData); }
        for (i,c) in s_trim.chars().enumerate() {
            if !c.is_ascii_hexdigit() { return Err(EthabiError::HexInvalidChar(c,i)); }
        }
        let bytes = hex::decode(s_trim).map_err(|_| EthabiError::InvalidData)?;
        let mut arr = [0u8;32];
        arr.copy_from_slice(&bytes);
        Ok(arr)
    }
}

pub fn parse_fixed_bytes(s: &str, n: usize, _lenient: bool) -> Result<Vec<u8>, EthabiError> {
    let s_trim = s.trim();
    let stripped = if s_trim.starts_with("0x") || s_trim.starts_with("0X") { &s_trim[2..] } else { s_trim };
    if stripped.len() %2 !=0 { return Err(EthabiError::HexOdd); }
    if stripped.len() != n*2 { return Err(EthabiError::InvalidData); }
    for (i,c) in stripped.chars().enumerate() {
        if !c.is_ascii_hexdigit() { return Err(EthabiError::HexInvalidChar(c,i)); }
    }
    let bytes = hex::decode(stripped).map_err(|_| EthabiError::InvalidData)?;
    Ok(bytes)
}

pub fn parse_bytes(s: &str, _lenient: bool) -> Result<Vec<u8>, EthabiError> {
    let s_trim = s.trim();
    if s_trim.is_empty() { return Ok(vec![]); }
    let stripped = if s_trim.starts_with("0x") || s_trim.starts_with("0X") { &s_trim[2..] } else { s_trim };
    if stripped.is_empty() { return Ok(vec![]); }
    if stripped.len() %2 !=0 { return Err(EthabiError::HexOdd); }
    for (i,c) in stripped.chars().enumerate() {
        if !c.is_ascii_hexdigit() { return Err(EthabiError::HexInvalidChar(c,i)); }
    }
    let bytes = hex::decode(stripped).map_err(|_| EthabiError::InvalidData)?;
    Ok(bytes)
}

pub fn parse_token_value(type_: &ParamType, value_str: &str, lenient: bool) -> Result<Token, EthabiError> {
    match type_ {
        ParamType::Bool => { let b = parse_bool(value_str, lenient)?; Ok(Token::Bool(b)) },
        ParamType::Uint(bits) => { let bytes = parse_uint(value_str, *bits, lenient)?; Ok(Token::Uint(bytes)) },
        ParamType::Int(bits) => { let bytes = parse_int(value_str, *bits, lenient)?; Ok(Token::Int(bytes)) },
        ParamType::Address => { let addr = parse_address(value_str, lenient)?; Ok(Token::Address(addr)) },
        ParamType::FixedBytes(n) => { let bytes = parse_fixed_bytes(value_str, *n, lenient)?; Ok(Token::FixedBytes(bytes)) },
        ParamType::Bytes => { let bytes = parse_bytes(value_str, lenient)?; Ok(Token::Bytes(bytes)) },
        ParamType::String => Ok(Token::String(value_str.to_string())),
        ParamType::Array(inner) => {
            let trimmed = value_str.trim();
            if !trimmed.starts_with('[') || !trimmed.ends_with(']') { return Err(EthabiError::InvalidData); }
            let inner_str = &trimmed[1..trimmed.len()-1];
            if inner_str.trim().is_empty() { return Ok(Token::Array(vec![])); }
            let elements = split_array_elements(inner_str)?;
            let mut tokens = Vec::new();
            for el in elements {
                let el_trim = el.trim();
                tokens.push(parse_token_value(inner, el_trim, lenient)?);
            }
            Ok(Token::Array(tokens))
        },
        ParamType::FixedArray(inner, len) => {
            let trimmed = value_str.trim();
            if !trimmed.starts_with('[') || !trimmed.ends_with(']') { return Err(EthabiError::InvalidData); }
            let inner_str = &trimmed[1..trimmed.len()-1];
            if inner_str.trim().is_empty() {
                if *len==0 { return Ok(Token::FixedArray(vec![])); } else { return Err(EthabiError::InvalidData); }
            }
            let elements = split_array_elements(inner_str)?;
            if elements.len() != *len { return Err(EthabiError::InvalidData); }
            let mut tokens = Vec::new();
            for el in elements {
                let el_trim = el.trim();
                tokens.push(parse_token_value(inner, el_trim, lenient)?);
            }
            Ok(Token::FixedArray(tokens))
        },
        ParamType::Tuple(types) => {
            let trimmed = value_str.trim();
            if !trimmed.starts_with('(') || !trimmed.ends_with(')') { return Err(EthabiError::InvalidData); }
            let inner_str = &trimmed[1..trimmed.len()-1];
            let elements = if inner_str.trim().is_empty() {
                vec![]
            } else {
                split_tuple_string(inner_str).map_err(|_| EthabiError::InvalidData)?
            };
            if elements.len() != types.len() { return Err(EthabiError::InvalidData); }
            let mut tokens = Vec::new();
            for (t, v) in types.iter().zip(elements.iter()) {
                tokens.push(parse_token_value(t, v.trim(), lenient)?);
            }
            Ok(Token::Tuple(tokens))
        }
    }
}

fn split_array_elements(s: &str) -> Result<Vec<String>, EthabiError> {
    let mut res = Vec::new();
    let mut current = String::new();
    let mut depth_bracket = 0;
    let mut depth_paren = 0;
    let mut in_quotes = false;
    let mut quote_char = '"';
    let chars: Vec<char> = s.chars().collect();
    let mut i=0;
    while i<chars.len() {
        let c = chars[i];
        if in_quotes {
            current.push(c);
            if c == quote_char { in_quotes = false; }
            i+=1;
            continue;
        }
        match c {
            '"' | '\'' => { in_quotes = true; quote_char = c; current.push(c); },
            '[' => { depth_bracket+=1; current.push(c); },
            ']' => { depth_bracket-=1; current.push(c); },
            '(' => { depth_paren+=1; current.push(c); },
            ')' => { depth_paren-=1; current.push(c); },
            ',' => {
                if depth_bracket==0 && depth_paren==0 {
                    res.push(current.trim().to_string());
                    current = String::new();
                } else { current.push(c); }
            },
            _ => { current.push(c); }
        }
        i+=1;
    }
    if !current.trim().is_empty() { res.push(current.trim().to_string()); }
    Ok(res)
}

pub fn encode_params_tokens(tokens: Vec<Token>) -> String {
    fn is_dynamic(tok: &Token) -> bool {
        match tok {
            Token::String(_) => true,
            Token::Bytes(_) => true,
            Token::Array(_) => true,
            Token::FixedArray(arr) => arr.iter().any(|e| is_dynamic(e)),
            Token::Tuple(arr) => arr.iter().any(|e| is_dynamic(e)),
            _ => false,
        }
    }
    fn encode_static_token(tok: &Token) -> Vec<u8> {
        match tok {
            Token::Address(a) => { let mut out = vec![0u8;12]; out.extend_from_slice(a); out },
            Token::Bool(b) => { let mut out = vec![0u8;31]; out.push(if *b {1} else {0}); out },
            Token::Uint(b) => b.to_vec(),
            Token::Int(b) => b.to_vec(),
            Token::FixedBytes(b) => { let mut out = vec![0u8;32]; out[..b.len()].copy_from_slice(b); out },
            Token::FixedArray(arr) => { let mut out = Vec::new(); for e in arr { out.extend(encode_static_token(e)); } out },
            Token::Tuple(arr) => { let mut out = Vec::new(); for e in arr { out.extend(encode_static_token(e)); } out },
            _ => panic!("static on dynamic"),
        }
    }
    fn encode_uint_usize(n: usize) -> [u8;32] {
        let mut out = [0u8;32];
        let mut val = n;
        for i in (0..32).rev() { out[i] = (val & 0xFF) as u8; val >>=8; if val==0 { break; } }
        out
    }
    fn encode_dynamic_data(tok: &Token) -> Vec<u8> {
        match tok {
            Token::String(s) => {
                let bytes = s.as_bytes();
                let len = bytes.len();
                let mut out = Vec::new();
                out.extend_from_slice(&encode_uint_usize(len));
                let mut padded = bytes.to_vec();
                let pad = (32 - (len %32)) %32;
                padded.extend(vec![0u8;pad]);
                out.extend(padded);
                out
            },
            Token::Bytes(b) => {
                let len = b.len();
                let mut out = Vec::new();
                out.extend_from_slice(&encode_uint_usize(len));
                let mut padded = b.clone();
                let pad = (32 - (len %32)) %32;
                padded.extend(vec![0u8;pad]);
                out.extend(padded);
                out
            },
            Token::Array(arr) => {
                let mut out = Vec::new();
                out.extend_from_slice(&encode_uint_usize(arr.len()));
                let (h,t) = encode_list(arr);
                out.extend(h);
                out.extend(t);
                out
            },
            Token::FixedArray(arr) => {
                let (h,t) = encode_list(arr);
                let mut out = Vec::new();
                out.extend(h);
                out.extend(t);
                out
            },
            Token::Tuple(arr) => {
                let (h,t) = encode_list(arr);
                let mut out = Vec::new();
                out.extend(h);
                out.extend(t);
                out
            },
            _ => panic!("dynamic data on static"),
        }
    }
    fn encode_list(tokens: &[Token]) -> (Vec<u8>, Vec<u8>) {
        struct Item { is_dynamic: bool, head: Vec<u8>, tail: Vec<u8>, head_size: usize, }
        let mut items: Vec<Item> = Vec::new();
        for tok in tokens {
            let dyn_ = is_dynamic(tok);
            if dyn_ {
                let tail = encode_dynamic_data(tok);
                items.push(Item { is_dynamic: true, head: vec![0u8;32], tail, head_size: 32 });
            } else {
                let head = encode_static_token(tok);
                let sz = head.len();
                items.push(Item { is_dynamic: false, head, tail: vec![], head_size: sz });
            }
        }
        let total_head: usize = items.iter().map(|i| i.head_size).sum();
        let mut heads = Vec::with_capacity(total_head);
        let mut tails = Vec::new();
        let mut offset = total_head;
        for it in items {
            if it.is_dynamic {
                heads.extend_from_slice(&encode_uint_usize(offset));
                offset += it.tail.len();
                tails.extend(it.tail);
            } else {
                heads.extend(it.head);
            }
        }
        (heads, tails)
    }
    let (heads, tails) = encode_list(&tokens);
    let mut out = Vec::new();
    out.extend(heads);
    out.extend(tails);
    hex::encode(out)
}

pub fn decode_tokens(param_types: &[ParamType], data: &[u8]) -> Result<Vec<Token>, String> {
    fn is_dynamic_type(pt: &ParamType) -> bool {
        match pt {
            ParamType::String => true,
            ParamType::Bytes => true,
            ParamType::Array(_) => true,
            ParamType::FixedArray(inner, _) => is_dynamic_type(inner),
            ParamType::Tuple(types) => types.iter().any(|t| is_dynamic_type(t)),
            _ => false,
        }
    }
    fn decode_one(pt: &ParamType, data: &[u8], offset: usize) -> Result<(Token, usize), String> {
        if data.len() < offset + 32 { return Err("Invalid data".to_string()); }
        if is_dynamic_type(pt) {
            let off_bytes = &data[offset..offset+32];
            let off = u256_to_usize(off_bytes)?;
            if off >= data.len() { return Err("Invalid data".to_string()); }
            let token = decode_at(pt, data, off)?;
            Ok((token, offset+32))
        } else {
            let token = decode_at(pt, data, offset)?;
            let size = static_size(pt);
            Ok((token, offset+size))
        }
    }
    fn static_size(pt: &ParamType) -> usize {
        match pt {
            ParamType::Tuple(types) => { let mut sz=0; for t in types { sz+=static_size(t); } sz },
            ParamType::FixedArray(inner, len) => static_size(inner) * len,
            _ => 32,
        }
    }
    fn decode_at(pt: &ParamType, data: &[u8], at: usize) -> Result<Token, String> {
        match pt {
            ParamType::Address => {
                if data.len() < at+32 { return Err("Invalid data".to_string()); }
                let word = &data[at..at+32];
                let mut addr = [0u8;20];
                addr.copy_from_slice(&word[12..]);
                Ok(Token::Address(addr))
            },
            ParamType::Bool => {
                if data.len() < at+32 { return Err("Invalid data".to_string()); }
                let word = &data[at..at+32];
                for i in 0..31 { if word[i]!=0 { return Err("Invalid data".to_string()); } }
                if word[31]==0 { Ok(Token::Bool(false)) }
                else if word[31]==1 { Ok(Token::Bool(true)) }
                else { Err("Invalid data".to_string()) }
            },
            ParamType::Uint(_) => {
                if data.len() < at+32 { return Err("Invalid data".to_string()); }
                let mut arr = [0u8;32];
                arr.copy_from_slice(&data[at..at+32]);
                Ok(Token::Uint(arr))
            },
            ParamType::Int(_) => {
                if data.len() < at+32 { return Err("Invalid data".to_string()); }
                let mut arr = [0u8;32];
                arr.copy_from_slice(&data[at..at+32]);
                Ok(Token::Int(arr))
            },
            ParamType::FixedBytes(n) => {
                if data.len() < at+32 { return Err("Invalid data".to_string()); }
                let word = &data[at..at+32];
                let mut bytes = vec![0u8; *n];
                bytes.copy_from_slice(&word[..*n]);
                Ok(Token::FixedBytes(bytes))
            },
            ParamType::String => {
                if data.len() < at+32 { return Err("Invalid data".to_string()); }
                let len = u256_to_usize(&data[at..at+32])?;
                if data.len() < at+32+len { return Err("Invalid data".to_string()); }
                let str_bytes = &data[at+32..at+32+len];
                let s = String::from_utf8(str_bytes.to_vec()).map_err(|_| "Invalid data".to_string())?;
                Ok(Token::String(s))
            },
            ParamType::Bytes => {
                if data.len() < at+32 { return Err("Invalid data".to_string()); }
                let len = u256_to_usize(&data[at..at+32])?;
                if data.len() < at+32+len { return Err("Invalid data".to_string()); }
                let b = data[at+32..at+32+len].to_vec();
                Ok(Token::Bytes(b))
            },
            ParamType::Array(inner) => {
                if data.len() < at+32 { return Err("Invalid data".to_string()); }
                let len = u256_to_usize(&data[at..at+32])?;
                let mut tokens = Vec::new();
                let mut offset = at+32;
                for _ in 0..len {
                    let (tok, next) = decode_one(inner, data, offset)?;
                    tokens.push(tok);
                    offset = next;
                }
                Ok(Token::Array(tokens))
            },
            ParamType::FixedArray(inner, len) => {
                if is_dynamic_type(inner) {
                    let mut tokens = Vec::new();
                    let mut offset = at;
                    for _ in 0..*len {
                        let (tok, next) = decode_one(inner, data, offset)?;
                        tokens.push(tok);
                        offset = next;
                    }
                    Ok(Token::FixedArray(tokens))
                } else {
                    let mut tokens = Vec::new();
                    let mut offset = at;
                    for _ in 0..*len {
                        let tok = decode_at(inner, data, offset)?;
                        tokens.push(tok);
                        offset += static_size(inner);
                    }
                    Ok(Token::FixedArray(tokens))
                }
            },
            ParamType::Tuple(types) => {
                if is_dynamic_type(pt) {
                    let mut tokens = Vec::new();
                    let mut offset = at;
                    for t in types {
                        let (tok, next) = decode_one(t, data, offset)?;
                        tokens.push(tok);
                        offset = next;
                    }
                    Ok(Token::Tuple(tokens))
                } else {
                    let mut tokens = Vec::new();
                    let mut offset = at;
                    for t in types {
                        let tok = decode_at(t, data, offset)?;
                        tokens.push(tok);
                        offset += static_size(t);
                    }
                    Ok(Token::Tuple(tokens))
                }
            }
        }
    }
    fn u256_to_usize(bytes: &[u8]) -> Result<usize, String> {
        if bytes.len()!=32 { return Err("Invalid data".to_string()); }
        let mut res: usize = 0;
        for &b in bytes {
            if res > (usize::MAX >> 8) { return Err("Invalid data".to_string()); }
            res = (res << 8) | (b as usize);
        }
        Ok(res)
    }
    let mut tokens = Vec::new();
    let mut offset = 0;
    for pt in param_types {
        let (tok, next) = decode_one(pt, data, offset)?;
        tokens.push(tok);
        offset = next;
    }
    Ok(tokens)
}

pub fn token_to_string(pt: &ParamType, token: &Token) -> String {
    match (pt, token) {
        (ParamType::Address, Token::Address(a)) => hex::encode(a),
        (ParamType::Bool, Token::Bool(b)) => if *b { "true".to_string() } else { "false".to_string() },
        (ParamType::Uint(_), Token::Uint(bytes)) => {
            let s = hex::encode(bytes);
            let trimmed = s.trim_start_matches('0');
            if trimmed.is_empty() { "0".to_string() } else { trimmed.to_string() }
        },
        (ParamType::Int(_), Token::Int(bytes)) => {
            if bytes[0] & 0x80 !=0 { hex::encode(bytes) }
            else {
                let s = hex::encode(bytes);
                let trimmed = s.trim_start_matches('0');
                if trimmed.is_empty() { "0".to_string() } else { trimmed.to_string() }
            }
        },
        (ParamType::FixedBytes(_), Token::FixedBytes(b)) => hex::encode(b),
        (ParamType::Bytes, Token::Bytes(b)) => hex::encode(b),
        (ParamType::String, Token::String(s)) => s.clone(),
        (ParamType::Array(inner), Token::Array(arr)) => {
            let inner_strs: Vec<String> = arr.iter().map(|t| token_to_string(inner, t)).collect();
            format!("[{}]", inner_strs.join(","))
        },
        (ParamType::FixedArray(inner,_), Token::FixedArray(arr)) => {
            let inner_strs: Vec<String> = arr.iter().map(|t| token_to_string(inner, t)).collect();
            format!("[{}]", inner_strs.join(","))
        },
        (ParamType::Tuple(types), Token::Tuple(arr)) => {
            let inner_strs: Vec<String> = arr.iter().zip(types.iter()).map(|(t,typ)| token_to_string(typ, t)).collect();
            format!("({})", inner_strs.join(","))
        },
        _ => format!("{:?}", token),
    }
}

pub fn token_to_display_with_type(pt: &ParamType, token: &Token) -> String {
    let type_str = canonical_type(pt);
    let val_str = token_to_string(pt, token);
    format!("{} {}", type_str, val_str)
}

pub fn event_param_to_string(param: &AbiParam, token: &Token) -> String {
    let val_str = token_to_string(&param.param_type, token);
    format!("{} {}", param.name, val_str)
}

pub fn encode_function_wrapper(abi_path: &str, func_name_or_sig: &str, params: &[String], lenient: bool) -> Result<String, String> {
    let entries = parse_abi_file(abi_path).map_err(|e| e)?;
    let func = find_function(&entries, func_name_or_sig)?;
    if params.len() != func.inputs.len() { return Err("Invalid data".to_string()); }
    let mut tokens = Vec::new();
    for (param, value) in func.inputs.iter().zip(params.iter()) {
        match parse_token_value(&param.param_type, value, lenient) {
            Ok(t) => tokens.push(t),
            Err(e) => return Err(e.to_string()),
        }
    }
    let encoded_params = encode_params_tokens(tokens);
    let selector = selector_for_function(func);
    let selector_hex = hex::encode(selector);
    Ok(format!("{}{}", selector_hex, encoded_params))
}

pub fn encode_params_wrapper(types_and_params: Vec<(String,String)>, lenient: bool) -> Result<String, String> {
    let mut tokens = Vec::new();
    for (type_str, value_str) in types_and_params {
        let pt = parse_param_type(&type_str).map_err(|_| "Invalid data".to_string())?;
        match parse_token_value(&pt, &value_str, lenient) {
            Ok(t) => tokens.push(t),
            Err(e) => return Err(e.to_string()),
        }
    }
    Ok(encode_params_tokens(tokens))
}

pub fn decode_function_wrapper(abi_path: &str, func_name_or_sig: &str, data_str: &str) -> Result<Vec<String>, String> {
    let entries = parse_abi_file(abi_path).map_err(|e| e)?;
    let func = find_function(&entries, func_name_or_sig)?;
    let data_bytes = parse_hex_strict(data_str).map_err(|e| e.to_string())?;
    if data_bytes.is_empty() {
        if func.outputs.is_empty() {
            return Ok(vec![]);
        } else {
            return Err("Invalid name: please ensure the contract and method you're calling exist! failed to decode empty bytes. if you're using jsonrpc this is likely due to jsonrpc returning `0x` in case contract or method don't exist".to_string());
        }
    }
    if func.outputs.is_empty() {
        return Ok(vec![]);
    }
    let output_types: Vec<ParamType> = func.outputs.iter().map(|p| p.param_type.clone()).collect();
    match decode_tokens(&output_types, &data_bytes) {
        Ok(tokens) => {
            let mut lines = Vec::new();
            for (pt, tok) in output_types.iter().zip(tokens.iter()) {
                lines.push(token_to_display_with_type(pt, tok));
            }
            Ok(lines)
        },
        Err(e) => Err(e),
    }
}

pub fn decode_params_wrapper(types: &[String], data_str: &str) -> Result<Vec<String>, String> {
    let mut param_types = Vec::new();
    for t in types {
        let pt = parse_param_type(t).map_err(|_| "Invalid data".to_string())?;
        param_types.push(pt);
    }
    if data_str.trim().is_empty() {
        return Err("Invalid data".to_string());
    }
    let data_bytes = parse_hex_strict(data_str).map_err(|e| e.to_string())?;
    match decode_tokens(&param_types, &data_bytes) {
        Ok(tokens) => {
            let mut lines = Vec::new();
            for (pt, tok) in param_types.iter().zip(tokens.iter()) {
                lines.push(token_to_display_with_type(pt, tok));
            }
            Ok(lines)
        },
        Err(e) => Err(e),
    }
}

pub fn decode_log_wrapper(abi_path: &str, event_name_or_sig: &str, data_str: &str, topics: &[String]) -> Result<Vec<String>, String> {
    let entries = parse_abi_file(abi_path).map_err(|e| e)?;
    let event = match find_event(&entries, event_name_or_sig) {
        Ok(ev) => ev,
        Err(msg) => return Err(msg),
    };
    let mut topic_bytes_list: Vec<Vec<u8>> = Vec::new();
    for t in topics {
        match parse_hex_strict(t) {
            Ok(b) => {
                if b.len()!=32 { return Err("Invalid data".to_string()); }
                topic_bytes_list.push(b);
            },
            Err(e) => return Err(e.to_string()),
        }
    }
    let data_bytes = parse_hex_strict(data_str).map_err(|e| e.to_string())?;
    let event_sig = {
        let mut s = String::new();
        s.push_str(&event.name);
        s.push('(');
        for (i, inp) in event.inputs.iter().enumerate() {
            if i>0 { s.push(','); }
            s.push_str(&canonical_type(&inp.param_type));
        }
        s.push(')');
        keccak256(s.as_bytes())
    };
    let indexed_params: Vec<&AbiParam> = event.inputs.iter().filter(|p| p.indexed).collect();
    let non_indexed_params: Vec<&AbiParam> = event.inputs.iter().filter(|p| !p.indexed).collect();

    let topics_for_indexed: Vec<Vec<u8>>;
    if event.anonymous {
        if topic_bytes_list.len() != indexed_params.len() { return Err("Invalid data".to_string()); }
        topics_for_indexed = topic_bytes_list;
    } else {
        if topic_bytes_list.len() != indexed_params.len() + 1 { return Err("Invalid data".to_string()); }
        if topic_bytes_list[0] != event_sig.to_vec() { return Err("Invalid data".to_string()); }
        topics_for_indexed = topic_bytes_list[1..].to_vec();
    }

    let mut decoded_indexed_tokens: Vec<Token> = Vec::new();
    for (param, topic_bytes) in indexed_params.iter().zip(topics_for_indexed.iter()) {
        if is_dynamic_type_for_event(&param.param_type) {
            decoded_indexed_tokens.push(Token::FixedBytes(topic_bytes.clone()));
        } else {
            match decode_static_from_word(&param.param_type, topic_bytes) {
                Ok(t) => decoded_indexed_tokens.push(t),
                Err(e) => return Err(e),
            }
        }
    }

    let non_indexed_types: Vec<ParamType> = non_indexed_params.iter().map(|p| p.param_type.clone()).collect();
    let decoded_non_indexed = if non_indexed_types.is_empty() {
        if data_bytes.is_empty() { vec![] } else { return Err("Invalid data".to_string()); }
    } else {
        decode_tokens(&non_indexed_types, &data_bytes).map_err(|e| e)?
    };

    let mut result_lines: Vec<String> = Vec::new();
    let mut indexed_idx = 0;
    let mut non_indexed_idx = 0;
    for param in &event.inputs {
        if param.indexed {
            let token = &decoded_indexed_tokens[indexed_idx];
            let display = if is_dynamic_type_for_event(&param.param_type) {
                if let Token::FixedBytes(b) = token {
                    format!("{} {}", param.name, hex::encode(b))
                } else {
                    format!("{} {}", param.name, "???")
                }
            } else {
                event_param_to_string(param, token)
            };
            result_lines.push(display);
            indexed_idx+=1;
        } else {
            let token = &decoded_non_indexed[non_indexed_idx];
            result_lines.push(event_param_to_string(param, token));
            non_indexed_idx+=1;
        }
    }
    Ok(result_lines)
}

fn is_dynamic_type_for_event(pt: &ParamType) -> bool {
    match pt {
        ParamType::String => true,
        ParamType::Bytes => true,
        ParamType::Array(_) => true,
        ParamType::FixedArray(inner,_) => is_dynamic_type_for_event(inner),
        ParamType::Tuple(types) => types.iter().any(|t| is_dynamic_type_for_event(t)),
        _ => false,
    }
}

fn decode_static_from_word(pt: &ParamType, word: &[u8]) -> Result<Token, String> {
    if word.len()!=32 { return Err("Invalid data".to_string()); }
    match pt {
        ParamType::Address => {
            let mut addr = [0u8;20];
            addr.copy_from_slice(&word[12..]);
            Ok(Token::Address(addr))
        },
        ParamType::Bool => {
            for i in 0..31 { if word[i]!=0 { return Err("Invalid data".to_string()); } }
            if word[31]==0 { Ok(Token::Bool(false)) }
            else if word[31]==1 { Ok(Token::Bool(true)) }
            else { Err("Invalid data".to_string()) }
        },
        ParamType::Uint(_) => {
            let mut arr = [0u8;32];
            arr.copy_from_slice(word);
            Ok(Token::Uint(arr))
        },
        ParamType::Int(_) => {
            let mut arr = [0u8;32];
            arr.copy_from_slice(word);
            Ok(Token::Int(arr))
        },
        ParamType::FixedBytes(n) => {
            let mut bytes = vec![0u8; *n];
            bytes.copy_from_slice(&word[..*n]);
            Ok(Token::FixedBytes(bytes))
        },
        _ => Err("Invalid data".to_string()),
    }
}
