            eprintln!("    executable decode params [OPTIONS] <data>");
            eprintln!();
            eprintln!("For more information try --help");
            std::process::exit(1);
        } else {
            if i==all.len()-1 {
                data=Some(a.clone());
                i+=1;
            } else {
                eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context", a);
                eprintln!();
                eprintln!("USAGE:");
                eprintln!("    executable decode params -v <type-or-param> <type-or-param>");
                eprintln!();
                eprintln!("For more information try --help");
                std::process::exit(1);
            }
        }
    }
    if data.is_none() {
        // Check if last element is a type that should be data but we treated as missing
        // If the last arg after -t is the only remaining and there are types already, data is that last arg, but we broke early
        // Actually if we broke because -t at end, data is None
        eprintln!("error: The following required arguments were not provided:");
