        eprintln!("    executable decode params <data> -t <type>...");
        eprintln!();
        eprintln!("For more information try --help");
        std::process::exit(1);
    }
    match crate::ethabi_impl::decode_params_wrapper(&types, &data.unwrap()) {
        Ok(lines) => { for l in lines { println!("{}", l); } },
        Err(e) => { eprintln!("Error: {}", e); std::process::exit(1); }
    }
}

