    if all.is_empty() {
        eprintln!("error: The following required arguments were not provided:");
        eprintln!("    <data>");
        eprintln!();
        eprintln!("USAGE:");
        eprintln!("    executable decode params <data> -t <type>...");
        eprintln!();
        eprintln!("For more information try --help");
        std::process::exit(1);
    }
    for a in &all {
        if a=="-h" || a=="--help" {
            print_decode_params_help(&args[0]);
            return;
        }
        if a=="-V" || a=="--version" {
            println!("executable-decode-params 18.0.0");
            return;
        }
    }
    let mut types: Vec<String> = Vec::new();
    let mut data: Option<String> = None;
    let mut i=0;
    while i<all.len() {
        let a=&all[i];
        if a=="-t" {
            i+=1;
            if i>=all.len() {
                // If -t without value, treat as missing data? Original still says missing data, not missing -t value
                // Let's check: decode params -t bool -t => original says missing data, not missing -t value
                // So if -t at end, we consider data missing
                break;
            }
            while i<all.len() {
                let nxt=&all[i];
                if nxt.starts_with("-") { break; }
                if i==all.len()-1 { break; }
                types.push(nxt.clone());
                i+=1;
            }
        } else if a.starts_with("-") {
            eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context", a);
            eprintln!();
            eprintln!("USAGE:");
            eprintln!("    executable decode params [OPTIONS] <data>");
            eprintln!();
            eprintln!("For more information try --help");
            std::process::exit(1);
        } else {
            if i==all.len()-1 {
                data=Some(a.clone());
                i+=1;
            } else {
                eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context", a);
                eprintln!();
                eprintln!("USAGE:");
                eprintln!("    executable decode params -v <type-or-param> <type-or-param>");
                eprintln!();
                eprintln!("For more information try --help");
                std::process::exit(1);
            }
        }
    }
    if data.is_none() {
        // Check if last element is a type that should be data but we treated as missing
        // If the last arg after -t is the only remaining and there are types already, data is that last arg, but we broke early
        // Actually if we broke because -t at end, data is None
        eprintln!("error: The following required arguments were not provided:");
        eprintln!("    <data>");
        eprintln!();
        eprintln!("USAGE:");
        eprintln!("    executable decode params <data> -t <type>...");
        eprintln!();
        eprintln!("For more information try --help");
        std::process::exit(1);
    }
    match crate::ethabi_impl::decode_params_wrapper(&types, &data.unwrap()) {
        Ok(lines) => { for l in lines { println!("{}", l); } },
        Err(e) => { eprintln!("Error: {}", e); std::process::exit(1); }
    }
}

