fn handle_decode_params(args: &[String]) {
    let all: Vec<String>=args.iter().skip(3).cloned().collect();
    if all.is_empty() {
        eprintln!("error: The following required arguments were not provided:");
        eprintln!("    <data>");
        eprintln!();
        eprintln!("USAGE:");
        eprintln!("    executable decode params <data> -t <type>...");
        eprintln!();
        eprintln!("For more information try --help");
        std::process::exit(1);
    }
    for a in &all {
        if a=="-h" || a=="--help" {
            print_decode_params_help(&args[0]);
            return;
        }
        if a=="-V" || a=="--version" {
            println!("executable-decode-params 18.0.0");
            return;
        }
    }
    // New logic: collect types after -t, and data is last arg if it exists and is not a flag.
    // For ["-t","bool"] -> types=["bool"], data missing
    // For ["-t","bool","data"] -> types=["bool"], data=data
    // For ["-t","bool","-t","uint","data"] -> types=["bool","uint"], data=data
    // For ["-t","bool","-t"] -> types=["bool"], data missing (second -t without value)
    // For ["data"] -> types=[], data=data
    let mut types: Vec<String> = Vec::new();
    let mut data: Option<String> = None;
    let mut i=0;
    while i<all.len() {
        let a=&all[i];
        if a=="-t" {
            i+=1;
            if i>=all.len() {
                // -t at end without type and without data -> missing data
                break;
            }
            // collect types until next -t or until only one arg left which will be data
            while i<all.len() {
                let nxt=&all[i];
                if nxt.starts_with("-") && nxt != "-t" {
                    break;
                }
                if nxt=="-t" { break; }
                // If this is last arg, it is data, not type
                if i==all.len()-1 {
                    // last arg is data
                    break;
                }
                types.push(nxt.clone());
                i+=1;
            }
        } else if a.starts_with("-") {
            eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context", a);
            eprintln!();
            eprintln!("USAGE:");
            eprintln!("    executable decode params [OPTIONS] <data>");
            eprintln!();
            eprintln!("For more information try --help");
            std::process::exit(1);
        } else {
            // positional
            if i==all.len()-1 {
                data=Some(a.clone());
                i+=1;
            } else {
                eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context", a);
                eprintln!();
                eprintln!("USAGE:");
                eprintln!("    executable decode params -v <type-or-param> <type-or-param>");
                eprintln!();
                eprintln!("For more information try --help");
                std::process::exit(1);
            }
        }
    }
    if data.is_none() {
        eprintln!("error: The following required arguments were not provided:");
        eprintln!("    <data>");
        eprintln!();
        eprintln!("USAGE:");
        eprintln!("    executable decode params <data> -t <type>...");
        eprintln!();
        eprintln!("For more information try --help");
        std::process::exit(1);
    }
    match crate::ethabi_impl::decode_params_wrapper(&types, &data.unwrap()) {
        Ok(lines) => { for l in lines { println!("{}", l); } },
        Err(e) => { eprintln!("Error: {}", e); std::process::exit(1); }
    }
}

