fn handle_decode_params(args: &[String]) {
    let all: Vec<String>=args.iter().skip(3).cloned().collect();
    if all.is_empty() {
        eprintln!("error: The following required arguments were not provided:");
        eprintln!("    <data>");
        eprintln!();
        eprintln!("USAGE:");
        eprintln!("    executable decode params <data> -t <type>...");
        eprintln!();
        eprintln!("For more information try --help");
        std::process::exit(1);
    }
    for a in &all {
        if a=="-h" || a=="--help" {
            print_decode_params_help(&args[0]);
            return;
        }
        if a=="-V" || a=="--version" {
            println!("executable-decode-params 18.0.0");
            return;
        }
    }
    // Parse types and data: types can be multiple after each -t, data is last arg that is not a valid type? We try to detect data as last positional that is not preceded by -t as type?
    // Better: try to parse last arg as data: if it is valid hex (even length?) then it's data. If all last arg is after -t and is a valid param type, then it's actually a type and data missing.
    // We'll implement as:
    // - Iterate all args, collecting types when after -t.
    // - Keep track of pending data candidate.
    // Approach: loop with index, expecting flag.
    let mut types: Vec<String> = Vec::new();
    let mut data: Option<String> = None;
    let mut i=0;
    while i<all.len() {
        let a=&all[i];
        if a=="-t" {
            i+=1;
            if i>=all.len() {
                // -t without value at end -> missing data (original says missing data)
                break;
            }
            // collect consecutive args that are valid param types as types, until next flag or last arg which could be data
            while i<all.len() {
                let nxt=&all[i];
                if nxt.starts_with("-") { break; }
                // Check if nxt is valid param type
                let is_type = crate::ethabi_impl::parse_param_type(nxt).is_ok();
                if !is_type {
                    // This is data candidate, break
                    break;
                }
                // If this is last arg, then it is type and data missing (since data cannot be a valid type)
                if i==all.len()-1 {
                    types.push(nxt.clone());
                    i+=1;
                    break;
                }
                types.push(nxt.clone());
                i+=1;
            }
        } else if a.starts_with("-") {
            eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context", a);
            eprintln!();
            eprintln!("USAGE:");
            eprintln!("    executable decode params [OPTIONS] <data>");
            eprintln!();
            eprintln!("For more information try --help");
            std::process::exit(1);
        } else {
            // positional arg not after -t: should be data if it's last
            if i==all.len()-1 {
                data=Some(a.clone());
                i+=1;
            } else {
                eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context", a);
                eprintln!();
                eprintln!("USAGE:");
                eprintln!("    executable decode params -v <type-or-param> <type-or-param>");
                eprintln!();
                eprintln!("For more information try --help");
                std::process::exit(1);
            }
        }
    }
    if data.is_none() {
        eprintln!("error: The following required arguments were not provided:");
        eprintln!("    <data>");
        eprintln!();
        eprintln!("USAGE:");
        eprintln!("    executable decode params <data> -t <type>...");
        eprintln!();
        eprintln!("For more information try --help");
        std::process::exit(1);
    }
    match crate::ethabi_impl::decode_params_wrapper(&types, &data.unwrap()) {
        Ok(lines) => { for l in lines { println!("{}", l); } },
        Err(e) => { eprintln!("Error: {}", e); std::process::exit(1); }
    }
}

